// V4.31.performance: one shared volume, available in creation and fullscreen performance.
{
 const slider=document.getElementById('volume');let lastVolume=100;
 const panels=[];
 function setVolume(value){slider.value=String(Math.max(0,Math.min(100,value)));slider.dispatchEvent(new Event('input',{bubbles:true}));}
 function sync(){const v=+slider.value;if(v>0)lastVolume=v;for(const p of panels){p.range.value=String(v);p.readout.textContent=v+'%';p.mute.textContent=v===0?'恢复声音':'静音';p.mute.setAttribute('aria-pressed',String(v===0));p.down.disabled=v===0;p.up.disabled=v===100;}}
 function controls(original){const box=document.createElement('div');box.className='volume-controls';box.style.cssText='display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 0';box.setAttribute('role','group');box.setAttribute('aria-label','播放音量');const label=document.createElement('span');label.textContent='音量';const range=original?slider:slider.cloneNode();if(!original){range.id='stageVolume';range.oninput=()=>setVolume(+range.value);}range.style.width='110px';const readout=document.createElement('output');readout.style.minWidth='38px';const down=document.createElement('button');down.type='button';down.textContent='−';down.setAttribute('aria-label','减小音量');down.onclick=()=>setVolume(+slider.value-10);const up=document.createElement('button');up.type='button';up.textContent='＋';up.setAttribute('aria-label','增大音量');up.onclick=()=>setVolume(+slider.value+10);const mute=document.createElement('button');mute.type='button';mute.onclick=()=>setVolume(+slider.value===0?lastVolume:0);box.append(label,down,range,up,readout,mute);panels.push({range,readout,down,up,mute});return box;}
 const oldLabel=slider.closest('label'), main=controls(true);oldLabel.replaceWith(main);
 const stage=controls(false);document.getElementById('stagePlay').parentElement.after(stage);
 slider.addEventListener('input',sync);sync();
}

