// Local, once-per-module onboarding. No analytics or network calls.
{
 const key='sonify-performance-v421-guide',ids=['chooseDraw','chooseText','choosePhoto','showArtwork'];let seen={};try{seen=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
 const titles=['用手画','Aa 输入文字','上传图片','完成创作'];const messages=['让笔尖与傅里叶变换起舞','文字的变换之美，快来试试看','内置本地图像分割模型，帮你提取主体轮廓（哦，先生，复杂图片恐怕得花些时间；不过，全程离线，不消耗 token）。','少年去探索去创作吧！（尘封多年的画布，期待着大师的回归......）'];
 const dialog=document.createElement('dialog');dialog.id='performanceGuide';dialog.setAttribute('aria-labelledby','guideTitle');dialog.innerHTML='<div class="guide-top"><span>✦ 创作导览</span><span id="guideNumber"></span></div><h2 id="guideTitle"></h2><p id="guideMessage"></p><figure id="guideMaterial"><img id="guideGif" alt="手绘圆链逐渐转为傅里叶旋转绘图的完整循环"><figcaption>材料 1 · Jez Swanson / 傅里叶变换交互式入门<br>由原网页开场动画转为 GIF · jezzamon.com/fourier</figcaption></figure><p id="guidePS" style="font-size:12px;color:#81938b">PS：你会发现它是无始无终的......</p><div class="guide-actions"><button class="primary" id="guideGotIt">我知道了</button></div>';
 const body=document.createElement('div');body.className='guide-body';while(dialog.firstChild)body.appendChild(dialog.firstChild);dialog.appendChild(body);document.body.appendChild(dialog);let active=0,previous=null,advancing=false;
 const style=document.createElement('style');style.textContent='#performanceGuide{box-sizing:border-box;width:min(520px,calc(100vw - 32px));max-height:90vh;overflow:auto;border:1px solid #c7d9e5;border-radius:20px;padding:24px;background:#fffefb;color:#294d47;box-shadow:0 18px 70px #173d4533}#performanceGuide::backdrop{background:#dce9f04d;backdrop-filter:blur(2px)}#performanceGuide h2{margin:16px 0 10px;font-size:24px}#performanceGuide p{font-size:17px;line-height:1.8;margin:10px 0}.guide-top{display:flex;justify-content:space-between;color:#678a9c;font-size:13px}.guide-actions{display:flex;justify-content:flex-end;margin-top:18px}#guideMaterial{margin:12px 0}#guideGif{display:block;width:min(280px,100%);margin:auto;border-radius:12px}#guideMaterial figcaption{color:#81938b;font-size:10px;line-height:1.6;text-align:center;margin-top:8px}.guide-target{outline:3px solid #80b9d5;outline-offset:4px}@media(max-height:650px){#guideGif{width:180px}#performanceGuide{padding:18px}}';document.head.appendChild(style);
 function show(i){if(seen[i]||dialog.open)return;active=i;advancing=true;document.getElementById(i===3?'chooseDraw':ids[i]).click();advancing=false;document.getElementById(ids[i]).scrollIntoView({block:'start',behavior:'instant'});previous=document.activeElement;document.getElementById(ids[i]).classList.add('guide-target');document.getElementById('guideTitle').textContent=titles[i];document.getElementById('guideNumber').textContent=(i+1)+' / 4';document.getElementById('guideMessage').textContent=messages[i];document.getElementById('guideMaterial').hidden=i!==0;document.getElementById('guidePS').hidden=i!==0;if(i===0)document.getElementById('guideGif').src=window.PERFORMANCE_GUIDE_GIF;dialog.showModal();position();document.getElementById('guideGotIt').focus({preventScroll:true});}
 function close(){seen[active]=true;try{localStorage.setItem(key,JSON.stringify(seen));}catch{}document.getElementById(ids[active]).classList.remove('guide-target');dialog.close();if(active<3){show(active+1);}else{previous?.focus({preventScroll:true});}}
 document.getElementById('guideGotIt').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});
 ids.slice(0,3).forEach((id,i)=>document.getElementById(id).addEventListener('click',()=>{if(!advancing)show(i);}));
 const replay=document.createElement('button');replay.id='replayGuide';replay.textContent='查看导览';replay.type='button';replay.onclick=()=>{seen={};try{localStorage.removeItem(key);}catch{}document.getElementById('chooseDraw').click();};document.querySelector('.intro').appendChild(replay);
 
 const directional=document.createElement('style');directional.textContent='#performanceGuide{position:fixed;margin:0;overflow:visible;padding:0;max-height:none}#performanceGuide .guide-body{padding:22px;overflow:auto;max-height:var(--guide-height,75vh);border-radius:20px}#performanceGuide::before{content:"";position:absolute;top:-10px;left:var(--guide-arrow,30px);width:18px;height:18px;background:#fffefb;border-left:1px solid #c7d9e5;border-top:1px solid #c7d9e5;transform:rotate(45deg)}#performanceGuide::backdrop{backdrop-filter:none;background:#dce9f028}#guideGif{width:200px}.guide-target{scroll-margin-top:18px;color:#294d47!important;background:#e1f0f8!important;outline:3px solid #65a6cb!important}';document.head.appendChild(directional);
 function position(){if(!dialog.open)return;const b=document.getElementById(ids[active]).getBoundingClientRect(),width=Math.min(520,innerWidth-32),left=Math.max(16,Math.min(innerWidth-width-16,b.left)),top=Math.max(16,Math.min(innerHeight-180,b.bottom+18));dialog.style.width=width+'px';dialog.style.left=left+'px';dialog.style.top=top+'px';dialog.style.setProperty('--guide-height',Math.max(140,innerHeight-top-18)+'px');dialog.style.setProperty('--guide-arrow',Math.max(16,Math.min(width-36,b.left+b.width/2-left-9))+'px');}
 window.addEventListener('resize',position);window.addEventListener('scroll',position,{passive:true});
 setTimeout(()=>show([0,1,2,3].find(i=>!seen[i])??0),350);
}

